<?php
require __DIR__.'/reports_financial.php';require_once APPPATH.'services/CompanyApiService.php';
if($db->driver()==='mysql')CompanyApiSchema::ensure($db,$p);else foreach(CompanyApiSchema::definitions() as $table=>$fields){$parts=[];foreach($fields as $name=>$type)$parts[]='`'.$name.'` '.str_replace(' NULL','',$type).(str_ends_with($type,' NULL')?' NULL':' NOT NULL');$parts[]='PRIMARY KEY('.($table==='company_api_tokens'?'token_id':'request_key').')';$db->query('CREATE TABLE '.$p.$table.'('.implode(',',$parts).')');}
$tokens=new CompanyApiTokens($db,$p);$api=new CompanyApiService($db,$p);$issued=$tokens->issue($a,7,'Synthetic integration',['invoices:read','invoices:pdf','invoices:create','reports:read'],30,$ck('api-issue'));$secret=$issued['secret'];
essentialCheck(is_string($secret)&&preg_match('/^crmco_[a-f0-9]{32}_[a-f0-9]{64}$/D',$secret)===1,'dedicated API secret carries independent 256-bit random credential');
$stored=$db->query('SELECT * FROM '.$p.'company_api_tokens WHERE token_id=?',[$issued['token_id']])->row_array();essentialCheck($stored['token_hash']===hash('sha256',$secret)&&!str_contains(json_encode($stored),$secret),'only hash persisted; full secret absent from row');
$retry=$tokens->issue($a,7,'Synthetic integration',['invoices:read','invoices:pdf','invoices:create','reports:read'],30,$ck('api-issue'));essentialCheck($retry['token_id']===$issued['token_id']&&$retry['secret']===null,'creation retry never redisplays secret or creates duplicate');
essentialCheck($api->invoices($secret)['issuer_id']===$a&&count($api->invoices($secret)['items'])>0,'API token reads own invoices without browser company/session');
essentialThrows(fn()=>$api->invoice($secret,$ib),'issuer_document_scope_mismatch','API bearer cannot fetch foreign invoice id');essentialCheck(str_starts_with($api->invoicePdf($secret,$invoice),'%PDF-'),'API own PDF actual TCPDF after token authorization audit');
essentialCheck($api->financial($secret)['issuer_id']===$a,'report API preserves immutable token company');
$created=$api->createInvoice($secret,$input,$ck('api-invoice'));$again=$api->createInvoice($secret,$input,$ck('api-invoice'));essentialCheck($created['invoice_id']===$again['invoice_id']&&!$created['replayed']&&$again['replayed'],'API create routes legitimate writer with durable idempotence');
$otherInput=$input;$otherInput['items'][0]['rate']='7.00';essentialThrows(fn()=>$api->createInvoice($secret,$otherInput,$ck('api-invoice')),'company_invoice_request_conflict','API repeated key with changed financial payload conflicts');
$other=$tokens->issue($b,7,'B private',['invoices:read'],30,$ck('api-b'));essentialCheck($api->invoices($other['secret'])['issuer_id']===$b,'B credential works only in B');essentialThrows(fn()=>$api->createInvoice($other['secret'],$input,$ck('api-scope')),'company_api_scope_denied','read-only token cannot invoke writer even master staff');
essentialThrows(fn()=>$tokens->revoke($b,7,$issued['token_id']),'company_api_access_denied','token administration cannot cross company');
$db->failOn='INSERT INTO '.$p.'issuers_audit';essentialThrows(fn()=>$tokens->issue($a,7,'Rollback',['invoices:read'],1,$ck('api-rollback')),'issuer_storage_failed','token creation audit failure rolls back secret metadata');essentialThrows(fn()=>$api->invoices($secret),'issuer_storage_failed','API read returns no financial data if authorization audit fails');$db->failOn=null;
$rotated=$tokens->issue($a,7,'Synthetic integration',['invoices:read','invoices:pdf','invoices:create','reports:read'],30,$ck('api-rotate'),$issued['token_id']);essentialThrows(fn()=>$api->invoices($secret),'company_api_unauthenticated','atomic rotation revokes previous bearer');essentialCheck($api->invoices($rotated['secret'])['issuer_id']===$a,'rotated credential has identical company and explicit scopes');
$tokens->revoke($a,7,$rotated['token_id']);$tokens->revoke($a,7,$rotated['token_id']);essentialThrows(fn()=>$api->invoices($rotated['secret']),'company_api_unauthenticated','revocation immediately blocks saved bearer');
$db->query('UPDATE '.$p.'company_api_tokens SET expires_at=? WHERE token_id=?',['2000-01-01 00:00:00',$other['token_id']]);essentialThrows(fn()=>$api->invoices($other['secret']),'company_api_unauthenticated','expired B token denied');
// Staff loses only one capability while immutable token scopes remain unchanged.
$db->query('UPDATE '.$p.'issuers_staff SET can_view=1 WHERE issuer_id=? AND staff_id=12',[$a]);foreach([['company_api','manage'],['invoices','view']] as [$feature,$cap])$db->query('INSERT IGNORE INTO '.$p.'issuers_resource_permissions(issuer_id,staff_id,feature,capability) VALUES(?,12,?,?)',[$a,$feature,$cap]);
$staff=$tokens->issue($a,12,'Explicit staff',['invoices:read'],1,$ck('api-staff'));essentialCheck($api->invoices($staff['secret'])['issuer_id']===$a,'non-master explicit token uses current staff grants');$db->query('DELETE FROM '.$p.'issuers_resource_permissions WHERE issuer_id=? AND staff_id=12 AND feature=?',[$a,'invoices']);essentialThrows(fn()=>$api->invoices($staff['secret']),'company_api_scope_denied','lost resource grant revokes corresponding saved bearer scope');
essentialThrows(fn()=>$api->invoices('legacy_token_does_not_authorize'),'company_api_unauthenticated','generic legacy token cannot authenticate dedicated API');
echo 'Company API token/scope/rotation/financial writer: '.$GLOBALS['essentialChecks'].' cumulative checks passed ('.$db->driver().'). No external calls.'.PHP_EOL;
